	    if (f.isDirectory()) {
		deleteFiles(f, f.list());
		if (f.delete() == false)
		    throw new IOException("Can't delete :" + f);
	    } else {
		if (f.delete() == false)
		    throw new IOException("Can't delete :" + f);
	    }
	}
    }

