	outln();
	out("\t\treturn \"");
	out(className);
	out("{\"");
	boolean first = true;
	for (Node field : fields) {
		if (!first) {
			out(" + \",\"");
		}
		NamedNodeMap fieldAttributes = field.getAttributes();
		String fieldName = fieldAttributes.getNamedItem("name").getNodeValue();
